static const case_full *find_full(const case_full *t, size_t n, uint32_t cp)
{
    size_t lo = 0, hi = n;
    while (lo < hi) {
        size_t mid = (lo + hi) / 2;
        if (t[mid].cp == cp) return &t[mid];
        if (t[mid].cp < cp) lo = mid + 1; else hi = mid;
    }
    return NULL;
}

static uint32_t find_simple(const case_simple *t, size_t n, uint32_t cp)
{
    size_t lo = 0, hi = n;
    while (lo < hi) {
        size_t mid = (lo + hi) / 2;
        if (t[mid].cp == cp) return t[mid].to;
        if (t[mid].cp < cp) lo = mid + 1; else hi = mid;
    }
    return cp;
}

#define COUNT(a) (sizeof(a) / sizeof((a)[0]))

/* Character.toUpperCase(int) and Character.toLowerCase(int). */
static uint32_t up1(uint32_t cp) { return find_simple(upper_simple, COUNT(upper_simple), cp); }
static uint32_t lo1(uint32_t cp) { return find_simple(lower_simple, COUNT(lower_simple), cp); }

int uni_digit(uint32_t cp)
{
    size_t lo = 0, hi = COUNT(digit_runs);
    while (lo < hi) {
        size_t mid = (lo + hi) / 2;
        if (cp < digit_runs[mid].first) hi = mid;
        else if (cp >= digit_runs[mid].first + digit_runs[mid].count) lo = mid + 1;
        else return (int)(cp - digit_runs[mid].first);
    }
    return -1;
}

static int wb_class(uint32_t cp)
{
    size_t lo = 0, hi = COUNT(wb_runs);
    while (hi - lo > 1) {
        size_t mid = (lo + hi) / 2;
        if (wb_runs[mid].first <= cp) lo = mid; else hi = mid;
    }
    return wb_runs[lo].cls;
}

static bool is_cased(uint32_t cp)
{
    size_t lo = 0, hi = COUNT(cased_ranges);
    while (lo < hi) {
        size_t mid = (lo + hi) / 2;
        if (cp < cased_ranges[mid][0]) hi = mid;
        else if (cp > cased_ranges[mid][1]) lo = mid + 1;
        else return true;
    }
    return false;
}

/* --- code points ------------------------------------------------- */

static bool is_high(uint32_t u) { return u >= 0xD800 && u <= 0xDBFF; }
static bool is_low(uint32_t u)  { return u >= 0xDC00 && u <= 0xDFFF; }

static uint32_t pair(uint32_t hi, uint32_t lo)
{
    return 0x10000 + ((hi - 0xD800) << 10) + (lo - 0xDC00);
}

/* The code point that starts at s[i], and its unit count in *w. */
static uint32_t cp_at(const uint16_t *s, size_t n, size_t i, size_t *w)
{
    if (is_high(s[i]) && i + 1 < n && is_low(s[i + 1])) { *w = 2; return pair(s[i], s[i + 1]); }
    *w = 1;
    return s[i];
}

/* The code point a unit belongs to: a surrogate joins the unit on its
 * other side when the two make a pair. */
static uint32_t cp_around(const uint16_t *s, size_t n, size_t k)
{
    if (is_high(s[k]) && k + 1 < n && is_low(s[k + 1])) return pair(s[k], s[k + 1]);
    if (is_low(s[k]) && k > 0 && is_high(s[k - 1])) return pair(s[k - 1], s[k]);
    return s[k];
}

/* --- buffer ------------------------------------------------------ */

typedef struct { uint16_t *u; size_t n, cap; } ubuf;

static void ub_put(ubuf *b, uint16_t v)
{
    if (b->n == b->cap) {
        size_t cap = b->cap ? b->cap * 2 : 16;
        uint16_t *nu = AUSSOM_ALLOC_ATOMIC(cap * sizeof(uint16_t));
        if (b->n > 0) memcpy(nu, b->u, b->n * sizeof(uint16_t));
        b->u = nu;
        b->cap = cap;
    }
    b->u[b->n++] = v;
}

static void ub_put_cp(ubuf *b, uint32_t cp)
{
    if (cp >= 0x10000) {
        cp -= 0x10000;
        ub_put(b, (uint16_t)(0xD800 + (cp >> 10)));
        ub_put(b, (uint16_t)(0xDC00 + (cp & 0x3FF)));
    } else {
        ub_put(b, (uint16_t)cp);
    }
}

/* --- comparison -------------------------------------------------- */

int64_t uni_compare(const uint16_t *a, size_t na, const uint16_t *b, size_t nb)
{
    size_t n = na < nb ? na : nb;
    for (size_t i = 0; i < n; i++) {
        if (a[i] != b[i]) return (int64_t)a[i] - (int64_t)b[i];
    }
    return (int64_t)na - (int64_t)nb;
}

static bool all_latin1(const uint16_t *s, size_t n)
{
    for (size_t i = 0; i < n; i++) if (s[i] > 0xFF) return false;
    return true;
}

/* Java walks both strings a unit at a time. Where two units differ it
 * compares them case-folded (upper case, then lower case). When neither
 * string fits in Latin-1, each differing unit is first widened to the
 * code point it is part of, so a surrogate pair folds as one
 * character; otherwise the units fold on their own. */
static bool fold_differs(const uint16_t *a, size_t na, const uint16_t *b, size_t nb,
                         size_t k, bool wide, int64_t *diff, bool *skip)
{
    uint32_t x = a[k], y = b[k];
    if (wide) { x = cp_around(a, na, k); y = cp_around(b, nb, k); }
    *skip = wide && x > 0xFFFF && is_high(a[k]);
    x = up1(x); y = up1(y);
    if (x == y) return false;
    x = lo1(x); y = lo1(y);
    if (x == y) return false;
    *diff = (int64_t)x - (int64_t)y;
    return true;
}

int64_t uni_compare_icase(const uint16_t *a, size_t na, const uint16_t *b, size_t nb)
{
    bool wide = !all_latin1(a, na) && !all_latin1(b, nb);
    size_t n = na < nb ? na : nb;
    for (size_t k = 0; k < n; k++) {
        if (a[k] == b[k]) continue;
        int64_t diff;
        bool skip;
        if (fold_differs(a, na, b, nb, k, wide, &diff, &skip)) return diff;
        if (skip) k++;
    }
    return (int64_t)na - (int64_t)nb;
}

bool uni_equals_icase(const uint16_t *a, size_t na, const uint16_t *b, size_t nb)
{
    if (na != nb) return false;
    bool wide = !all_latin1(a, na) && !all_latin1(b, nb);
    for (size_t k = 0; k < na; k++) {
        if (a[k] == b[k]) continue;
        int64_t diff;
        bool skip;
        if (fold_differs(a, na, b, nb, k, wide, &diff, &skip)) return false;
        if (skip) k++;
    }
    return true;
}

/* --- case mapping ------------------------------------------------ */

uint16_t *uni_to_upper(const uint16_t *s, size_t n, size_t *out_n)
{
    ubuf b = { NULL, 0, 0 };
    for (size_t i = 0; i < n;) {
        size_t w;
        uint32_t cp = cp_at(s, n, i, &w);
        const case_full *f = find_full(upper_full, COUNT(upper_full), cp);
        if (f != NULL) for (int k = 0; k < f->n; k++) ub_put(&b, f->u[k]);
        else ub_put_cp(&b, cp);
        i += w;
    }
    *out_n = b.n;
    return b.u != NULL ? b.u : AUSSOM_ALLOC_ATOMIC(sizeof(uint16_t));
}

/* --- word boundaries, for final sigma ----------------------------
 *
 * String.toLowerCase gives a capital sigma its final form when a cased
 * character (Character.isUpperCase, isLowerCase or isTitleCase) comes
 * before it in the same word and none comes after it in that word. The
 * words are those of java.text.BreakIterator.getWordInstance(), as a
 * newly made iterator's isBoundary reports them. That behavior was
 * worked out by probing the JDK 23 runtime, not from its source:
 *
 * - Forward segmentation: from a boundary, run the machine above over
 *   the characters' classes and end the word at the last accepting
 *   position, or at the end of the text when the machine is still
 *   alive there and the state allows it (wb_eof). U+FFFF reads as the
 *   end of the text, and a U+FFFF at the start of a word stands alone.
 * - isBoundary(i) is that segmentation, except right after a
 *   supplementary-class character (classes 23 to 30): there it is
 *   always a boundary, unless that character starts the text or follows
 *   U+FFFF, when it is a boundary only if the character is a word by
 *   itself.
 */

typedef struct {
    size_t n;          /* characters */
    uint32_t *cp;      /* code points (an unpaired surrogate is its own) */
    uint8_t *cls;      /* their word-break classes */
    size_t *at;        /* unit index of each character; at[n] = length */
    bool *seg;         /* boundary before character k, forward segmentation */
} wb_text;

static bool wb_supp(int cls) { return cls >= 23 && cls <= 30; }

/* The end of the word that starts at character p, segmenting forward. */
static size_t wb_word_end(const wb_text *t, size_t p)
{
    if (t->cls[p] == WB_FFFF) return p + 1;
    size_t end = t->n;
    for (size_t k = p + 1; k < t->n; k++) if (t->cls[k] == WB_FFFF) { end = k; break; }
    int q = WB_START;
    size_t last = 0;
    bool have = false, died = false;
    for (size_t i = p; i < end;) {
        q = wb_next[q][t->cls[i]];
        i++;
        if (!wb_live[q]) { died = true; break; }
        if (wb_accept[q]) { last = i; have = true; }
    }
    if (!died && wb_eof[q]) { last = end; have = true; }
    return have ? last : p + 1;
}

static void wb_read(wb_text *t, const uint16_t *s, size_t n)
{
    t->cp = AUSSOM_ALLOC_ATOMIC((n + 1) * sizeof(uint32_t));
    t->cls = AUSSOM_ALLOC_ATOMIC(n + 1);
    t->at = AUSSOM_ALLOC_ATOMIC((n + 1) * sizeof(size_t));
    t->seg = AUSSOM_ALLOC_ATOMIC(n + 1);
    size_t k = 0;
    for (size_t i = 0; i < n;) {
        size_t w;
        t->at[k] = i;
        t->cp[k] = cp_at(s, n, i, &w);
        t->cls[k] = (uint8_t)wb_class(t->cp[k]);
        k++;
        i += w;
    }
    t->at[k] = n;
    t->n = k;
    memset(t->seg, 0, k + 1);
    t->seg[0] = true;
    for (size_t p = 0; p < k;) {
        p = wb_word_end(t, p);
        t->seg[p] = true;
    }
}

/* A fresh word BreakIterator's isBoundary, before character k. */
static bool wb_is_boundary(const wb_text *t, size_t k)
{
    if (k == 0 || k == t->n) return true;
    if (wb_supp(t->cls[k - 1])) {
        if (k - 1 == 0 || t->cls[k - 2] == WB_FFFF) return wb_word_end(t, k - 1) == k;
        return true;
    }
    return t->seg[k];
}

/* Whether the capital sigma that is character k lowers to the final
 * form. */
static bool final_sigma(const wb_text *t, size_t k)
{
    bool before = false;
    for (size_t i = k; i > 0 && !wb_is_boundary(t, i); i--) {
        if (is_cased(t->cp[i - 1])) { before = true; break; }
    }
    if (!before) return false;
    for (size_t i = k + 1; i < t->n && !wb_is_boundary(t, i); i++) {
        if (is_cased(t->cp[i])) return false;
    }
    return true;
}

uint16_t *uni_to_lower(const uint16_t *s, size_t n, size_t *out_n)
{
    ubuf b = { NULL, 0, 0 };
    wb_text t;
    bool words = false;
    size_t k = 0;
    for (size_t i = 0; i < n; k++) {
        size_t w;
        uint32_t cp = cp_at(s, n, i, &w);
        if (cp == 0x03A3) {
            /* The words are found once, and only when a sigma needs them. */
            if (!words) { wb_read(&t, s, n); words = true; }
            ub_put(&b, final_sigma(&t, k) ? 0x03C2 : 0x03C3);
        } else {
            const case_full *f = find_full(lower_full, COUNT(lower_full), cp);
            if (f != NULL) for (int j = 0; j < f->n; j++) ub_put(&b, f->u[j]);
            else ub_put_cp(&b, cp);
        }
        i += w;
    }
    *out_n = b.n;
    return b.u != NULL ? b.u : AUSSOM_ALLOC_ATOMIC(sizeof(uint16_t));
}

/* --- searching --------------------------------------------------- */

int64_t uni_index_of(const uint16_t *s, size_t n, const uint16_t *needle, size_t nn, int64_t from)
{
    if (from < 0) from = 0;
    if (from > (int64_t)n) from = (int64_t)n;
    if (nn > n) return -1;
    for (size_t i = (size_t)from; i + nn <= n; i++) {
        if (nn == 0 || memcmp(s + i, needle, nn * sizeof(uint16_t)) == 0) return (int64_t)i;
    }
    return -1;
}

int64_t uni_last_index_of(const uint16_t *s, size_t n, const uint16_t *needle, size_t nn, int64_t from)
{
    int64_t last = (int64_t)n - (int64_t)nn;
    if (last < 0) return -1;
    if (from > last) from = last;
    for (int64_t i = from; i >= 0; i--) {
        if (nn == 0 || memcmp(s + i, needle, nn * sizeof(uint16_t)) == 0) return i;
    }
    return -1;
}
